package com.ekayn.api.service;
import com.ekayn.api.api.ApiModels.*; import com.ekayn.api.model.*; import com.ekayn.api.repo.*; import org.junit.jupiter.api.*; import org.mockito.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
class OrderServiceTest {
  @Mock OrderRepository orders; @Mock AddressRepository addresses; @Mock NotificationService notifications; OrderService service;
  @BeforeEach void setup(){MockitoAnnotations.openMocks(this);service=new OrderService(orders,addresses,notifications);}
  private User user(){User u=new User();u.setId(UUID.randomUUID());u.setFirstName("A");u.setLastName("Client");return u;}
  private Address address(User user){Address a=new Address();a.setId(UUID.randomUUID());a.setUser(user);a.setLine1("1 rue Test");a.setCity("Paris");a.setPostalCode("75001");a.setCountry("FR");return a;}
  @Test void refusesOrderDetailsBelongingToAnotherCustomer(){User a=user();when(orders.findByIdAndUserId(any(),eq(a.getId()))).thenReturn(Optional.empty());assertThrows(NoSuchElementException.class,()->service.mineOne(a,UUID.randomUUID()));}
  @Test void recalculatesStandardDeliveryFromServerCatalog(){User u=user();Address a=address(u);when(addresses.findByIdAndUserId(any(),eq(u.getId()))).thenReturn(Optional.of(a));when(orders.save(any())).thenAnswer(inv->inv.getArgument(0));var created=service.create(u,new OrderInput(List.of(new ItemInput("1",null,2)),a.getId(),"STANDARD_HOME_DELIVERY"),"key-1");assertEquals("39.80",created.getSubtotal().toPlainString());assertEquals("6.90",created.getShippingCost().toPlainString());assertEquals("46.70",created.getTotal().toPlainString());assertEquals("Livraison à domicile avec suivi",created.getShippingMethodLabel());}
  @Test void shippingIsFreeFrom69Euros(){User u=user();Address a=address(u);when(addresses.findByIdAndUserId(any(),eq(u.getId()))).thenReturn(Optional.of(a));var quote=service.quote(u,new OrderInput(List.of(new ItemInput("2",null,2)),a.getId(),"STANDARD_HOME_DELIVERY"));assertEquals("119.80",quote.subtotal().toPlainString());assertEquals(0,quote.shippingCost().compareTo(java.math.BigDecimal.ZERO));}
  @Test void storesImmutableAddressSnapshot(){User u=user();Address a=address(u);when(addresses.findByIdAndUserId(any(),eq(u.getId()))).thenReturn(Optional.of(a));when(orders.save(any())).thenAnswer(inv->inv.getArgument(0));var created=service.create(u,new OrderInput(List.of(new ItemInput("1",null,1)),a.getId(),"STANDARD_HOME_DELIVERY"),"key-2");assertTrue(created.getShippingAddressSnapshot().contains("1 rue Test"));a.setLine1("Nouvelle adresse");assertTrue(created.getShippingAddressSnapshot().contains("1 rue Test"));}
  @Test void adminShippingUpdateStoresTrackingAndNotifiesOnlyOnce(){User u=user();u.setEmail("client@example.com");var order=new com.ekayn.api.model.Order();order.setId(UUID.randomUUID());order.setUser(u);order.setShippingMethod(Enums.ShippingMethod.STANDARD_HOME_DELIVERY);order.setShippingMethodLabel("Livraison à domicile avec suivi");when(orders.findById(order.getId())).thenReturn(Optional.of(order));when(orders.save(any())).thenAnswer(inv->inv.getArgument(0));var shippedAt=java.time.Instant.parse("2026-01-02T10:00:00Z");var update=new DeliveryUpdate("EXPEDIEE","COLISSIMO","ABC123","https://tracking.example/ABC123",shippedAt);service.update(order.getId(),update);assertEquals("COLISSIMO",order.getCarrier());assertEquals("ABC123",order.getTrackingNumber());assertEquals(shippedAt,order.getShippedAt());verify(notifications,times(1)).shipped(order);service.update(order.getId(),update);verify(notifications,times(1)).shipped(order);}
}
